// T04 real-artifact integration tests: load artifacts generated by the current
// software compiler (device run dirs contain only manifest + image) and run the
// descriptor -> DMA -> scratchpad -> consumer copy -> DMA writeback loop.

#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>

#include "dataplane/selftest.hpp"
#include "nlohmann/json.hpp"

namespace {

int failures = 0;
int checks = 0;

void expect(bool condition, const std::string& message) {
    ++checks;
    if (!condition) {
        ++failures;
        std::cerr << "FAIL: " << message << '\n';
    }
}

std::vector<std::uint8_t> read_file(const std::filesystem::path& path) {
    std::ifstream input(path, std::ios::binary);
    return std::vector<std::uint8_t>(
        std::istreambuf_iterator<char>(input), std::istreambuf_iterator<char>());
}

std::string read_text(const std::filesystem::path& path) {
    std::ifstream input(path, std::ios::binary);
    return std::string(
        std::istreambuf_iterator<char>(input), std::istreambuf_iterator<char>());
}

}  // namespace

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "usage: dataplane_artifact_tests FIXTURES_DIR [OUTPUT_DIR]\n";
        return 2;
    }
    const std::filesystem::path fixtures_root = argv[1];
    const std::filesystem::path output_root = argc > 2 ? argv[2] : "";

    const auto metadata =
        nlohmann::json::parse(read_text(fixtures_root / "fixtures.json"));

    bool saw_static = false;
    bool saw_dynamic = false;
    bool saw_multinode = false;
    bool saw_multiroot = false;
    bool saw_large = false;

    for (const auto& item : metadata.at("cases")) {
        const std::string name = item.at("name").get<std::string>();
        const std::string policy = item.at("policy").get<std::string>();
        const std::filesystem::path device_dir =
            fixtures_root / name / "device";
        if (!std::filesystem::exists(device_dir / "manifest.json")) {
            ++failures;
            std::cerr << "FAIL: missing device dir for case " << name << '\n';
            continue;
        }
        // Device run directories contain only manifest.json and memory_image.bin.
        std::size_t file_count = 0;
        for (const auto& entry : std::filesystem::directory_iterator(device_dir)) {
            (void)entry;
            ++file_count;
        }
        expect(file_count == 2, name + ": device dir must have exactly two files");

        const auto image_before = read_file(device_dir / "memory_image.bin");

        hw::dataplane::DataPlaneSelftestOptions options;
        options.buffer_capacity_bytes = 64 * 1024;
        options.buffer_slots = 2;
        options.buffer_ports = 2;
        const auto out_dir =
            output_root.empty() ? std::string() : (output_root / name).string();
        const auto report = hw::dataplane::run_dataplane_selftest(
            device_dir.string(), options, out_dir);

        expect(report.ok, name + ": selftest failed: " + report.failure);
        expect(report.policy == policy, name + ": policy mismatch");
        expect(report.descriptor_reads > 0, name + ": descriptor reads must be counted");
        expect(report.dma_read_bytes > 0, name + ": DMA read bytes must be counted");
        expect(report.dma_write_bytes > 0, name + ": DMA write bytes must be counted");
        expect(report.tile_bytes > 0, name + ": tile must be non-empty");
        expect(
            report.tile_bytes <= options.buffer_capacity_bytes,
            name + ": tile must fit the configured capacity (capacity limits are reported)");

        // The device run directory is never modified by the data plane.
        const auto image_after = read_file(device_dir / "memory_image.bin");
        expect(image_before == image_after, name + ": device image must stay unchanged");

        if (!out_dir.empty()) {
            expect(std::filesystem::exists(out_dir + "/transactions.csv"),
                   name + ": transactions.csv written");
            expect(std::filesystem::exists(out_dir + "/buffers.csv"),
                   name + ": buffers.csv written");
            expect(std::filesystem::exists(out_dir + "/summary.json"),
                   name + ": summary.json written");
            expect(std::filesystem::exists(out_dir + "/final_memory_image.bin"),
                   name + ": final snapshot written");
            const auto summary =
                nlohmann::json::parse(read_text(out_dir + "/summary.json"));
            expect(summary.at("ok").get<bool>(), name + ": summary ok flag");
            expect(
                summary.at("verification").at("target_verified").get<bool>(),
                name + ": summary target verification");
            expect(
                summary.at("verification").at("control_regions_unchanged").get<bool>(),
                name + ": summary control region verification");
            expect(
                summary.at("transfer").at("writeback_note").get<std::string>().find(
                    "not a solved") != std::string::npos,
                name + ": writeback note must disclaim numerical meaning");
        }

        if (policy == "STATIC") {
            saw_static = true;
        }
        if (policy == "DYNAMIC_PANEL") {
            saw_dynamic = true;
        }
        if (item.at("node_count").get<int>() > 1) {
            saw_multinode = true;
        }
        if (item.at("roots").get<int>() > 1) {
            saw_multiroot = true;
        }
        if (name == "large_256") {
            saw_large = true;
            std::cout << "large_256 capacity report: image="
                      << report.image_bytes << " tile=" << report.tile_bytes
                      << " buffer_capacity=" << options.buffer_capacity_bytes
                      << '\n';
        }
    }

    expect(saw_static, "STATIC data contract covered");
    expect(saw_dynamic, "DYNAMIC_PANEL data contract covered");
    expect(saw_multinode, "multi-node artifact covered");
    expect(saw_multiroot, "multi-root artifact covered");
    expect(saw_large, "256-scale artifact smoke covered");

    std::cout << checks << " checks, " << failures << " failures\n";
    return failures == 0 ? 0 : 1;
}
